  ui_story_5007_50070101_112_dialog_content = "เมืองใต้ดินในแนวหลังก็น่าจะทราบเรื่องแล้วก็เริ่มอพยพคนได้แล้ว",
  ui_story_5007_50070101_113_dialog_content = "หรือว่า<color=#FFB400>ระบบสื่อสาร</color>ของพวกนั้นก็พังเหมือนกัน?",
  ui_story_5007_50070101_114_dialog_content = "มันอาจจะสายเกินไปที่จะถอนกำลัง... หรือบางทีพวกเขาอาจประเมินกองกำลังโจมตีของศัตรูต่ำเกินไป?",
  ui_story_5007_50070101_115_dialog_content = "ยังไงซะ ไปดูก่อนก็แล้วกัน",
  ui_story_5007_50070101_116_dialog_content = "<color=#FFB400>พายุทราย</color>ไงล่ะ!",
  ui_story_5007_50070201_1_dialog_content = "เร็วเข้า เราจะไปรวมพลกันตรงนั้น!",
  ui_story_5007_50070201_2_dialog_content = "เราจะไปไหนกันน่ะ? ตรงนั้นมันมีอะไรเหรอ?",
  ui_story_5007_50070201_3_dialog_content = "นี่ ใครทำกระสุนหล่นเต็มพื้นเลยเนี่ย?",
  ui_story_5007_50070201_4_dialog_content = "คุณเห็นรึเปล่าเนี่ยว่าเมืองใต้ดินมันวุ่นวายแค่ไหน หัวหน้า?",
  ui_story_5007_50070201_5_dialog_content = "เห็นแล้ว... เละเทะไปหมดเลย",
  ui_story_5007_50070201_6_dialog_content = "ถึงพวกนั้นจะเป็นทหารของอิลลูมินาเหมือนกัน แต่ก็ยังห่างชั้นจากกำลังรบหลักอยู่ดี!",
  ui_story_5007_50070201_7_dialog_content = "อืมม ถ้าทำเป็นไม่รู้ไม่เห็นเรื่องนั้นฉันก็ไม่มีปัญหาอะไรนะ อย่างที่เขาว่าไง โง่ไว้สบายใจกว่า!",
  ui_story_5007_50070201_8_dialog_content = "นี่ไม่ใช่เวลามาล้อเล่นกันนะ หัวหน้า",
  ui_story_5007_50070201_9_dialog_content = "ใจเย็นก่อนน่า เบรนท์",
  ui_story_5007_50070201_10_dialog_content = "ในเวลาแบบนี้นายจะต้องใจเย็นเข้าไว้ ไม่งั้นการตัดสินใจของนายก็จะไม่เด็ดขาด",
  ui_story_5007_50070201_11_dialog_content = "ขอโทษครับ คุณรู้มั้ยว่าปืนใหญ่อยู่ตรงไหน?",
  ui_story_5007_50070201_12_dialog_content = "ลองไปดูที่เชิงเทินฝั่งตะวันตกซิ!",
  ui_story_5007_50070201_13_dialog_content = "พลปืนใหญ่ที่หาปืนใหญ่ไม่เจองั้นเรอะ! ถ้าเจอทหารใส่กางเกงกลับด้านฉันคงไม่ต้องแปลกใจใช่มั้ยเนี่ย?!",
  ui_story_5007_50070201_14_dialog_content = "ชักจะเหลืออดแล้วนะ!",
  ui_story_5007_50070201_15_dialog_content = "ไม่ต้องหัวเสียขนาดนั้นหรอกน่า หมอนั่นอาจจะเพิ่งมาใหม่ก็ได้",
  ui_story_5007_50070201_16_dialog_content = "นี่ นาย! พลทหารตรงนั้นน่ะ!",
  ui_story_5007_50070201_17_dialog_content = "หมายถึงผมเหรอครับ?",
  ui_story_5007_50070201_18_dialog_content = "ทำไมพอเรียกแล้วต้องมุดไปหลบด้วย? คิดว่าฉันไม่เห็นหรือไง?",
  ui_story_5007_50070201_19_dialog_content = "เครื่องแบบของนายอยู่ไหน? ทำไมไม่เอามาใส่?",
  ui_story_5007_50070201_20_dialog_content = "เอ่อ พายุทรายพัดกางเกงผมหายไปน่ะครับ ผมหายังไงก็ไม่เจอ",
