  ui_story_5007_50070201_21_dialog_content = "เยี่ยมเลย มาครบทุกรูปแบบจริง ๆ ทำกางเกงหายงั้นเรอะ",
  ui_story_5007_50070201_22_dialog_content = "นี่มัน<color=#FFB400>กองทหารรวมมิตร</color>ชัด ๆ",
  ui_story_5007_50070201_23_dialog_content = "เราอยู่ในสภาพที่ออกรบได้จริง ๆ รึเปล่าเนี่ย หัวหน้า?",
  ui_story_5007_50070201_24_dialog_content = "ได้สิ แค่สู้กับอิคลิพไซท์น่ะ ใคร ๆ ก็ทำเป็นอยู่แล้ว",
