  ui_story_5007_50070201_29_dialog_content = "เอางั้นก็ได้ครับ รับทราบ",
  ui_story_5007_50070201_30_dialog_content = "ทีมเมืองใต้ดินหมายเลข 24 รวมพล!",
  ui_story_5007_50070201_31_dialog_content = "รายงานผลการลาดตระเวนมาซิ!",
  ui_story_5007_50070201_32_dialog_content = "จากรายงาน พายุทรายได้ผ่านไปแล้ว ทัศนวิสัยจึงกลับมาเป็นปกติ ตอนนี้เรามองเห็นได้ไกลมากเลยครับ",
