  ui_story_5007_50070201_36_dialog_content = "ฉันไม่ได้สอนนายแบบนั้นซักหน่อย! ช่างมันเหอะ รายงานต่อซิ!",
  ui_story_5007_50070201_37_dialog_content = "เราพบเห็นอิคลิพไซท์กำลังไล่ตาม<color=#FFB400>พาหนะขนส่ง</color>อยู่ครับ!",
  ui_story_5007_50070201_38_dialog_content = "คิดว่าอีกนานแค่ไหนรถนั่นจะมาถึง? แล้วพวกอิคลิพไซท์ที่ไล่ตามอยู่ล่ะ?",
