  ui_story_5007_50070801_24_dialog_content = "แจ้งทีมที่เหลือด้วย! ถ้าหัวหน้าอิคลิพไซท์บุกเข้ามาถึงสถานีได้ ก็ให้พยายามสกัดอิคลิพไซท์ตัวอื่น ๆ อย่างสุดกำลัง!",
