  ui_story_5007_50070801_26_dialog_content = "อัลลัวรา จัดการพวกมันซะ",
  ui_story_5007_50070801_27_dialog_content = "ถ้าเป็นฝีมือการยิงปืนของเธอคงจะไม่ลำบากใช่มั้ย",
  ui_story_5007_50070801_28_dialog_content = "ไม่มีปัญหา เดี๋ยวฉันไปจัดการให้ แล้วจะรีบกลับมานะ",
  ui_story_5007_50070801_29_dialog_content = "<color=#e8d9bb>ผับ ผับ ผับ</color>",
  ui_story_5007_50070801_30_dialog_content = "หวา! อิคลิพไซท์พวกนี้มาจากไหนน่ะ?!",
  ui_story_5007_50070801_31_dialog_content = "เปลวเพลิงจู่โจม!",
  ui_story_5007_50070801_32_dialog_content = "หา? นี่ฉันไปยั่วโมโหมันเหรอเนี่ย!",
  ui_story_5007_50070801_33_dialog_content = "<color=#e8d9bb>ปัง ปัง ปัง</color>",
  ui_story_5007_50070801_34_dialog_content = "...",
  ui_story_5007_50070801_35_dialog_content = "ว้าว แค่ยิงไม่กี่นัดก็ร่วงแล้ว...",
  ui_story_5007_50070801_36_dialog_content = "เธอมาทำอะไรตรงนี้น่ะ คอร์ดี้?",
  ui_story_5007_50070801_37_dialog_content = "ฉันไม่ใช่สายต่อสู้เท่าไหร่ ก็เลยคิดว่าจะช่วยจากในเมืองใต้ดินน่ะ",
  ui_story_5007_50070801_38_dialog_content = "พูดเป็นเล่นน่า?",
  ui_story_5007_50070801_39_dialog_content = "หมายความว่าไงน่ะ? ฉันเป็นผู้พิทักษ์กฎที่ไม่เคยออกรบ ยังไงฉันก็เป็นภาระในสนามรบเปล่า ๆ",
  ui_story_5007_50070801_40_dialog_content = "ฉันว่าเธอไม่รู้ถึงความแข็งแกร่งในตัวเองมากกว่านะ รู้มั้ยว่าเธอเอามือกระทุ้งฉันทีไร ฉันก็กลัวซี่โครงตัวเองจะหักทุกที",
  ui_story_5007_50070801_41_dialog_content = "หมายความว่าไงกันน่ะ? นี่จะหาเรื่องกันอีกแล้วหรือไง?",
  ui_story_5007_50070801_42_dialog_content = "ฉันแค่อยากบอกว่าเธอเองก็เป็นนักสู้ได้ แค่ขาดความตั้งใจและความกล้า",
  ui_story_5007_50070801_43_dialog_content = "แต่ก็ดีแล้วล่ะที่คอยช่วยอยู่ตรงนี้ เพราะอย่างน้อยมันก็ปลอดภัยกับเธอมากกว่า",
  ui_story_5007_50070801_44_dialog_content = "ยังไงที่นี่ก็ไม่มีพวกอิคลิพไซท์ซุ่มอยู่แน่ ๆ",
  ui_story_5007_50070801_45_dialog_content = "<color=#e8d9bb>โฮกก โฮกก...</color>",
  ui_story_5007_50070801_46_dialog_content = "เสียงอะไรน่ะ?",
  ui_story_5007_50070801_47_dialog_content = "รู้สึกใจคอไม่ดีเลยแฮะ...",
