  ui_story_5007_50070901_41_dialog_content = "เดี๋ยวก่อน ผมสัมผัสได้ว่าหัวหน้ามันอยู่ในสถานี!",
  ui_story_5007_50070901_42_dialog_content = "แต่พลังความมืดอ่อนแอมาก ๆ...",
  ui_story_5007_50070901_43_dialog_content = "เกิดอะไรกันนะ?",
  ui_story_5007_50070901_44_dialog_content = "กรร!",
  ui_story_5007_50070901_45_dialog_content = "รีบฆ่ามันให้เร็วที่สุด!",
  ui_story_5007_50070901_46_dialog_content = "แล้วเราจะกลับเมืองใต้ดินหมายเลข 24 เดี๋ยวนี้!",
  ui_story_5007_50070902_1_dialog_content = "สำเร็จมั้ย?",
  ui_story_5007_50070902_2_dialog_content = "ในซากนี้ไม่มีอะไรขยับแล้ว...",
  ui_story_5007_50070902_3_dialog_content = "เราระเบิดหัวหน้าอิคลิพไซท์เป็นผุยผง!",
  ui_story_5007_50070902_4_dialog_content = "ปฏิบัติการสำเร็จแล้ว!",
  ui_story_5007_50070902_5_dialog_content = "เราทำได้งั้นเหรอ? เราทำได้จริง ๆ น่ะเหรอ?",
  ui_story_5007_50070902_6_dialog_content = "เอ่อ เดี๋ยวก่อนนะ แล้วหัวหน้าเบรนท์ล่ะ?",
  ui_story_5007_50070902_7_dialog_content = "แค่ก แค่ก...",
  ui_story_5007_50070902_8_dialog_content = "ฉันได้ยินอะไรบางอย่าง...",
  ui_story_5007_50070902_9_dialog_content = "เสียงแหบ ๆ นั่น... เหมือนหัวหน้าเบรนท์เลย!",
  ui_story_5007_50070902_10_dialog_content = "หัวหน้าเบรนท์... โอ๊ย!",
  ui_story_5007_50070902_11_dialog_content = "เดินระวังหน่อยสิ จะได้ไม่สะดุด!",
  ui_story_5007_50070902_12_dialog_content = "ขอโทษค่ะ... คุณไม่เป็นไรนะคะ?",
  ui_story_5007_50070902_13_dialog_content = "ไม่เป็นไร แค่โดนฝังในซากเฉยๆ น่ะ...",
  ui_story_5007_50070902_14_dialog_content = "ฉันไม่ได้อยู่ที่จุดระเบิดตอนส่งสัญญาณ ก็เลยไม่บาดเจ็บอะไร",
  ui_story_5007_50070902_15_dialog_content = "ฮึก... เราทำได้จริง ๆ...",
  ui_story_5007_50070902_16_dialog_content = "เลิกร้องไห้ได้แล้ว ทหาร!",
  ui_story_5007_50070902_17_dialog_content = "ค่ะ...",
  ui_story_5007_50070902_18_dialog_content = "ส่งใครมารายงานสถานการณ์หน่อยซิ",
  ui_story_5007_50070902_19_dialog_content = "ฉันขอพักซักเดี๋ยว",
  ui_story_5007_50070902_20_dialog_content = "ได้ค่ะ!",
  ui_story_5007_50070902_21_dialog_content = "ผมได้รับรายงานจากหอระวังภัย",
  ui_story_5007_50070902_22_dialog_content = "ดูเหมือนอิคลิพไซท์ที่แนวข้างจะถอยทัพไปแล้ว",
  ui_story_5007_50070902_23_dialog_content = "แต่ฝูงใหญ่ก็ยังมุ่งหน้าเข้ามาที่สถานีอยู่",
  ui_story_5007_50070902_24_dialog_content = "หน่วยรบที่สู้อยู่ข้างนอกถอนกำลังกลับเข้ามาในสถานีแล้ว",
  ui_story_5007_50070902_25_dialog_content = "ตอนนี้พวกเขาต่อสู้โดยใช้อาคารเป็นที่กำบัง",
  ui_story_5007_50070902_26_dialog_content = "ข่าวดีก็คือ ตอนนี้พวกอิคลิพไซท์ช้าลงทั้งร่างกายและจิตใจ",
  ui_story_5007_50070902_27_dialog_content = "แล้ว PlayerName กับพรรคพวกล่ะ ได้ข่าวอะไรบ้างมั้ย?",
  ui_story_5007_50070902_28_dialog_content = "พวกเขาเห็นแสงพลังลูมินาที่ฝั่งตะวันออก",
  ui_story_5007_50070902_29_dialog_content = "แสดงว่าน่าจะมีออโรเรียนเดินทางกลับมาที่สถานี",
  ui_story_5007_50070902_30_dialog_content = "ต้องเป็นพวกนั้นแน่ ๆ! ใช่แล้วล่ะ! โอย...",
  ui_story_5007_50070902_31_dialog_content = "ไม่เป็นไรนะคะ?",
  ui_story_5007_50070902_32_dialog_content = "โอ้ รู้สึกดีสุด ๆ ไปเลยล่ะ!",
  ui_story_5007_50070902_33_dialog_content = "แกรมกับคนอื่น ๆ กำลังกลับมา",
  ui_story_5007_50070902_34_dialog_content = "รวบรวมคนที่ยังสู้ไหวกันเถอะ!",
  ui_story_5007_50070902_35_dialog_content = "ได้เวลาเอาคืนแล้ว!",
  ui_story_5007_50070902_36_dialog_content = "รับทราบ!",
  ui_story_5007_50070902_37_dialog_content = "เอาล่ะทุกคน ถึงเวลาแล้ว!",
  ui_story_5007_50070902_38_dialog_content = "คราวนี้เราจะเป็นฝ่ายบุกโจมตีพวกมันบ้าง!",
  ui_story_5007_50070902_39_dialog_content = "<anim type=Shake><size=42>ย้าาาาาา!</size></anim>",
  ui_story_5007_50070902_40_dialog_content = "บุก!",
  ui_story_5007_50070902_41_dialog_content = "ไม่ต้องปรานีพวกโสโครกนี่!",
  ui_story_5007_50070902_42_dialog_content = "เล็งปืนแล้วก็กระหน่ำยิงพวกมันให้สาสม!",
  ui_story_5007_50070902_43_dialog_content = "<color=#e8d9bb>ผลุบ</color>",
  ui_story_5007_50070902_44_dialog_content = "...",
  ui_story_5007_50070902_45_dialog_content = "(เสียงอะไรน่ะ?)",
  ui_story_5007_50070902_46_dialog_content = "(อย่าบอกนะ...)",
  ui_story_5007_50070902_47_dialog_content = "โฮก โฮก...",
  ui_story_5007_50070902_48_dialog_content = "(พับผ่าสิ!)",
  ui_story_5007_50070902_49_dialog_content = "(แกเป็นอมตะหรือยังไงกันน่ะ?)",
  ui_story_5007_50070902_50_dialog_content = "<color=#e8d9bb>ปัง!</color>",
  ui_story_5007_50070902_51_dialog_content = "อิคลิพไซท์ยังไม่ตาย มันออกมาจากซากอาคารแล้ว!",
  ui_story_5007_50070902_52_dialog_content = "โฮก!",
  ui_story_5007_50070902_53_dialog_content = "<size=45>หัวหน้าเบรนท์!</size>",
  ui_story_5007_50071001_1_dialog_content = "(เอาจริง ๆ เลยนะ ฉันมาทำอะไรในสนามรบกันแน่?)",
  ui_story_5007_50071001_2_dialog_content = "(เหมือนกับแกรมนั่นแหละ ฉันไม่อยากจะต่อสู้อีกแล้ว)",
  ui_story_5007_50071001_3_dialog_content = "(แต่ตาแก่หัวหน้าเมืองใต้ดินหมายเลข 24 ก็เอาแต่มากวนฉันอยู่เรื่อย)",
  ui_story_5007_50071001_4_dialog_content = "สโตนฟอร์ซสลายตัวหลังจากการเสียสละของเบอร์นาร์ด",
  ui_story_5007_50071001_5_dialog_content = "แล้วแกรมก็เสียใจอย่างหนัก",
  ui_story_5007_50071001_6_dialog_content = "ฉันจะไม่ทำตัวหดหู่แบบแกรมหรอกนะ",
  ui_story_5007_50071001_7_dialog_content = "แกรมแคร์คนอื่นมาก ๆ แต่ฉันไม่ใช่คนแบบนั้น",
  ui_story_5007_50071001_8_dialog_content = "แล้วมันต่างกันตรงไหนล่ะ?",
  ui_story_5007_50071001_9_dialog_content = "นายยังเด็กมาก เบรนท์",
  ui_story_5007_50071001_10_dialog_content = "แต่พวกนายทั้งคู่ก็เหมือนกัน!",
  ui_story_5007_50071001_11_dialog_content = "ทั้งสองคนเป็นทหารที่ดี เป็นนักสู้ที่เก่งกาจ ทนทายาด แถมข้างในก็ยังเป็นคนอ่อนโยน!",
  ui_story_5007_50071001_12_dialog_content = "เลิกพูดจาปลอบใจผมซักทีเถอะครับ",
  ui_story_5007_50071001_13_dialog_content = "ยิ่งพูด แผลเก่ามันก็ยิ่งเจ็บขึ้นมา",
  ui_story_5007_50071001_14_dialog_content = "โอ๊ะ ขอโทษที ฉันเคยบอกรึยังนะ ว่าฉันดีใจแค่ไหนที่นายมาเป็นครูฝึกให้เมืองใต้ดินหมายเลข 24?",
  ui_story_5007_50071001_15_dialog_content = "เราภูมิใจมาก ๆ ที่มีสมาชิกจากสโตนฟอร์ซอยู่ในเมืองตั้งสองคน!",
  ui_story_5007_50071001_16_dialog_content = "เรื่องก็ผ่านมานานแล้ว ตอนนี้ัมันไม่ใช่อะไรที่น่าภูมิใจหรอก",
  ui_story_5007_50071001_17_dialog_content = "แล้วแกรมก็ไม่อยากนึกถึงช่วงเวลานั้นแน่ ๆ เพราะงั้นอย่าไปพูดเรื่องนี้กับเขาเลยนะครับ",
  ui_story_5007_50071001_18_dialog_content = "เฮ้อ นึกว่านายสองคนจะเป็นเพื่อนซี้กันมานาน แค่คุยเคลียร์ใจกันยังทำไม่ได้เลยเหรอ?",
  ui_story_5007_50071001_19_dialog_content = "นายรู้จักเด็กผู้หญิงที่เพิ่งย้ายเข้าค่ายทหารใหม่รึเปล่า?",
  ui_story_5007_50071001_20_dialog_content = "เด็กไหนเหรอ?",
  ui_story_5007_50071001_21_dialog_content = "<color=#FFB400>ลูกของเบอร์นาร์ด</color> เพื่อนนายอีกคนไง",
  ui_story_5007_50071001_22_dialog_content = "เธอชื่อเรเวนตัน",
  ui_story_5007_50071001_23_dialog_content = "ต่อไปเธอจะอยู่ในการดูแลของนาย เพราะงั้นสอนเธอให้ดี ๆ ด้วยล่ะ",
  ui_story_5007_50071001_24_dialog_content = "สโตนฟอร์ซก่อตั้งขึ้นเมื่อ 26 ปีที่แล้ว",
  ui_story_5007_50071001_25_dialog_content = "นาย แกรม เบอร์นาร์ด กับเคเลสไทต์ที่มาทีหลัง...",
  ui_story_5007_50071001_26_dialog_content = "หน่วยของนายกลายเป็นทีมปาฏิหาริย์ที่ทำสิ่งเป็นไปไม่ได้สำเร็จเสมอ",
  ui_story_5007_50071001_27_dialog_content = "สุดท้ายเคเลสไทต์ก็กลับไปที่อีราเวล แล้วอิคลิพไซท์ก็บุกไปทำลายที่นั่น จากนั้นเราก็ไม่เคยพบเขาอีกเลย",
  ui_story_5007_50071001_28_dialog_content = "แต่เมื่อวิกฤตดาร์กโอเวอร์เกิดขึ้นเมื่อ 14 ปีที่แล้ว...",
  ui_story_5007_50071001_29_dialog_content = "นายก็รับช่วงต่อเจตจำนงของเคเลสไทต์ ทำให้ปาฏิหาริย์ของหน่วยในตำนานเกิดขึ้นอีกครั้ง และฆ่าอิคลิพไซท์ไปนับไม่ถ้วน",
  ui_story_5007_50071001_30_dialog_content = "ฉันมั่นใจว่านายคงรู้ ว่ามีทหารมากมายแค่ไหนที่ได้แรงบันดาลใจจากวีรกรรมของนายในวันนั้น",
  ui_story_5007_50071001_31_dialog_content = "และตอนนี้ เรวี่ก็รับช่วงต่อจากเบอร์นาร์ด และเธอก็เป็นนักรบที่ยอดเยี่ยม",
  ui_story_5007_50071001_32_dialog_content = "ได้เห็นพวกนายสองคนกลับมาร่วมมือกันอีกครั้งในวันนี้ มันเติมเต็มจริง ๆ",
  ui_story_5007_50071001_33_dialog_content = "ถ้าได้เห็นพวกนายทั้งสามคนต่อสู้เคียงบ่าเคียงไหล่กันอีกล่ะก็ นั่นคงจะเยี่ยมขึ้นไปอีก",
  ui_story_5007_50071001_34_dialog_content = "คงเป็นภาพในฝันเลยล่ะ! ฮ่าฮ่า",
  ui_story_5007_50071001_35_dialog_content = "จริงมั้ย เบรนท์?",
  ui_story_5007_50071001_36_dialog_content = "(นั่นสิ...)",
  ui_story_5007_50071001_37_dialog_content = "(พวกนั้นกลับมาเร็วจริง ๆ... อย่างที่คิดไว้เลย...)",
  ui_story_5007_50071001_38_dialog_content = "คุณเบรนท์!",
  ui_story_5007_50071001_39_dialog_content = "<size=40>หัวหน้าเบรนท์!</size>",
  ui_story_5007_50071001_40_dialog_content = "<size=45>เบรนท์!</size>",
