  ui_story_5007_50071001_42_dialog_content = "พลังเต็มพิกัด!",
  ui_story_5007_50071001_43_dialog_content = "ไหม้เป็นเถ้าถ่านไปซะ ไอ้พวกสัตว์ประหลาด!",
  ui_story_5007_50071001_44_dialog_content = "โฮก!",
  ui_story_5007_50071001_45_dialog_content = "มาสิ เบรนท์!",
