  ui_story_5007_50071101_62_dialog_content = "ไม่ต้องอ้างเรื่องไร้สาระอย่างหน้าอกใหญ่ต้านลมหรืออะไรพวกนั้นเลยนะ! ฉันบาดเจ็บอยู่ ยังไงเธอก็วิ่งเร็วกว่าอยู่แล้ว",
  ui_story_5007_50071101_62X_dialog_content = "ฉันไม่ได้จะพูดเรื่องนั้นซักหน่อย!",
  ui_story_5007_50071101_63_dialog_content = "งั้นก็ไปได้แล้ว! เร็วเข้า!",
  ui_story_5007_50071101_64_dialog_content = "ฉันจะจัดการทุกตัวที่ตามเธอมา!",
  ui_story_5007_50071101_65_dialog_content = "โฮกก!",
  ui_story_5007_50071101_66_dialog_content = "ระวังนะ ทหาร!",
  ui_story_5007_50071101_67_dialog_content = "กรร!",
  ui_story_5007_50071101_68_dialog_content = "ขอบคุณมาก อัศวินหอกขาว!",
  ui_story_5007_50071101_69_dialog_content = "เมื่อกี๊เรียกฉันว่าอัศวินหอกขาวงั้นเหรอ?",
  ui_story_5007_50071101_70_dialog_content = "ใช่... ก็ไม่รู้ว่าคุณเป็นใครนี่นา แต่ขอบคุณที่ช่วยนะ!",
  ui_story_5007_50071101_71_dialog_content = "ขอบคุณที่ทำให้ฉันยังมีชีวิต... จะได้กำจัดอิคลิพไซท์มากกว่านี้!",
  ui_story_5007_50071101_72_dialog_content = "บุก!",
  ui_story_5007_50071101_73_dialog_content = "สำหรับทหารอิลลูมินาก็ถือว่าเป็นคนน่าสนใจดี",
  ui_story_5007_50071101_74_dialog_content = "โฮกก!",
  ui_story_5007_50071101_75_dialog_content = "เรวี่ บุก!",
  ui_story_5007_50071101_76_dialog_content = "กรร!",
  ui_story_5007_50071101_77_dialog_content = "บุก!",
  ui_story_5007_50071101_78_dialog_content = "บุก! บุก!",
  ui_story_5007_50071101_79_dialog_content = "<size=30>นี่ เรวี่ ใจเย็นก่อน...</size>",
  ui_story_5007_50071101_80_dialog_content = "<size=30>มาช่วยฉันทีได้มั้ย...</size>",
  ui_story_5007_50071101_81_dialog_content = "เสียงอะไรน่ะ? แมลงงั้นเหรอ",
  ui_story_5007_50071101_82_dialog_content = "<size=30>ฉันอยู่นี่ ในหลุมน่ะ...</size>",
  ui_story_5007_50071101_83_dialog_content = "ไปนอนทำอะไรในนั้นน่ะ PlayerName?",
  ui_story_5007_50071101_84_dialog_content = "ฉันหล่นลงไปน่ะ ดึงฉันขึ้นไปทีสิ",
  ui_story_5007_50071101_85_dialog_content = "เดี๋ยวใช้แขนกลดึงให้นะ!",
  ui_story_5007_50071101_86_dialog_content = "เป็นแขนที่แข็งแรงชะมัด... มือฉันเกือบหักแน่ะ ขอบใจนะ!",
  ui_story_5007_50071101_87_dialog_content = "โฮกก โฮกก...",
  ui_story_5007_50071101_88_dialog_content = "ฉันจัดการอิคลิพไซท์ตรงนี้หมดแล้ว PlayerName",
  ui_story_5007_50071101_89_dialog_content = "เอาล่ะ! งั้นไปช่วยที่อื่นกันเถอะ!",
  ui_story_5007_50071101_90_dialog_content = "(ภาษาอิคลิพส์) ฆ่าออโรเรียน โจมตีเมืองใต้ดิน ทำลายเป้าหมาย",
  ui_story_5007_50071101_91_dialog_content = "(ภาษาอิคลิพส์) บุกเข้าไป",
  ui_story_5007_50071101_92_dialog_content = "รู้สึกมั้ยว่าการต่อสู้มันวุ่นวายไปหมดเลย?",
  ui_story_5007_50071101_93_dialog_content = "เอ๋? แต่ทุกคนก็ร่วมแรงร่วมใจกันดีนะ...",
  ui_story_5007_50071101_94_dialog_content = "โอ๊ะ จริงด้วย ทุกคนอยากจะให้มันเป็นระเบียบ แต่ที่จริงก็ไม่",
  ui_story_5007_50071101_95_dialog_content = "ใช่ พวกเขาขาดผู้บัญชาการ...",
  ui_story_5007_50071101_96_dialog_content = "อิคลิพไซท์เต็มไปหมดเลย! สิ้นหวังแล้ว!",
  ui_story_5007_50071101_97_dialog_content = "พวกมันบุกกันมาไม่จบไม่สิ้นซักที!",
  ui_story_5007_50071101_98_dialog_content = "มีคนบาดเจ็บอยู่ตรงนี้ ช่วยที!",
  ui_story_5007_50071101_99_dialog_content = "ทหาร ฉันจะคุ้มกันพวกนายให้ กลับไปที่สถานีซะ!",
  ui_story_5007_50071101_100_dialog_content = "เจ้าหน้าที่แกรม! ขอบคุณมากเลย!",
  ui_story_5007_50071101_101_dialog_content = "คุณกลับมา แสดงว่าเมืองนี้ปลอดภัยแล้วสินะ",
  ui_story_5007_50071101_102_dialog_content = "แต่...",
  ui_story_5007_50071101_103_dialog_content = "อิคลิพไซท์เยอะขนาดนั้น เราไม่มีทางต้านไหวแล้วล่ะ... คุณแกรม...",
  ui_story_5007_50071101_104_dialog_content = "(ภาษาอิคลิพส์) เดินหน้าต่อไป",
  ui_story_5007_50071101_105_dialog_content = "(ภาษาอิคลิพส์) ฆ่าพวกออโรเรียน",
  ui_story_5007_50071101_106_dialog_content = "ถอนกำลัง! ทิ้งแนวรบมาซะ!",
  ui_story_5007_50071101_107_dialog_content = "(ภาษาอิคลิพส์) ฆ่าพวกมันให้หมด",
  ui_story_5007_50071101_108_dialog_content = "ถอยไปที่สถานี!",
  ui_story_5007_50071101_109_dialog_content = "(ภาษาอิคลิพส์) บดขยี้พวกมันให้หมด",
  ui_story_5007_50071101_110_dialog_content = "ฉันต้านไว้ไม่อยู่แล้ว... ศึกครั้งนี้ยังไงเราก็ไม่ชนะ...",
  ui_story_5007_50071101_111_dialog_content = "<color=#e8d9bb>ฟิ้ววว!</color>",
  ui_story_5007_50071101_112_dialog_content = "เสียงอะไรน่ะ?",
  ui_story_5007_50071101_113_dialog_content = "ข้างบนนั่นมัน โคลอสซัสนี่นา!",
  ui_story_5007_50071101_114_dialog_content = "ทดสอบ ทดสอบ...",
  ui_story_5007_50071101_115_dialog_content = "สวัสดี!",
  ui_story_5007_50071101_116_dialog_content = "ได้ยินฉันมั้ย?",
  ui_story_5007_50071101_117_dialog_content = "ฉันแอนเซีย ถ่ายทอดสดจากบนฟ้า!",
  ui_story_5007_50071101_118_dialog_content = "เรากลับมาแล้ว... พร้อมกระสุนอีกเพียบ",
  ui_story_5007_50071101_119_dialog_content = "เราจะปกป้องเมืองใต้ดินหมายเลข 24 และจะต้องชนะให้ได้!",
  ui_story_5007_50071101_120_dialog_content = "ขอย้ำอีกครั้ง ขออิลลูมินาจงเจิดจำรัส!",
  ui_story_5007_50071101_121_dialog_content = "เราจะต้องชนะ!",
  ui_story_5007_50071101_122_dialog_content = "ได้ยินมั้ย? ไปพาพลปืนใหญ่กลับมาเร็ว!",
  ui_story_5007_50071101_123_dialog_content = "เรามีกระสุนแล้ว!",
  ui_story_5007_50071101_124_dialog_content = "ส่งคนไปตรงจุดที่โคลอสซัสลงจอด!",
  ui_story_5007_50071101_125_dialog_content = "เติมกระสุนเสร็จแล้วก็ยิงไอ้พวกบ้านั่นเลย!",
  ui_story_5007_50071101_126_dialog_content = "สั่งสอนพวกมันที่บังอาจเสนอหน้ามาที่นี่!",
  ui_story_5007_50071102_1_dialog_content = "อิคลิพไซท์ถอยทัพไปแล้ว!",
  ui_story_5007_50071102_2_dialog_content = "<size=45>เราชนะ!</size>",
  ui_story_5007_50071102_3_dialog_content = "เบรนท์... ได้ยินเสียงเชียร์นั่นรึเปล่า?",
  ui_story_5007_50071102_4_dialog_content = "โคลอสซัสส่งกระสุนเท่าที่หาได้มาให้เรา แล้วเราก็สาดกระสุนใส่พวกมัน 5 นาทีติดกัน",
  ui_story_5007_50071102_5_dialog_content = "ผู้เสียชีวิตส่วนใหญ่จากการต่อสู้คือทหารผ่านศึก พวกเขาต่อสู้อย่างกล้าหาญเหมือนนายในอดีต",
  ui_story_5007_50071102_6_dialog_content = "สุดท้ายอิคลิพไซท์ก็ถอยทัพ พวกเราเป็นฝ่ายชนะ",
  ui_story_5007_50071102_7_dialog_content = "...",
  ui_story_5007_50071102_8_dialog_content = "ฉันรู้ว่านายแข็งใจไว้ได้นานมาก ๆ พวกหมอเล่าให้ฉันฟังแล้ว",
  ui_story_5007_50071102_9_dialog_content = "ตอนนี้นายพักผ่อนอย่างวางใจได้แล้วล่ะ",
  ui_story_5007_50071102_10_dialog_content = "มันแปลกดีนะ นี่ทำให้ฉันนึกถึงตอนที่ได้เจอนายอีกครั้ง หลังจากศึกครั้งนั้น...",
  ui_story_5007_50071102_11_dialog_content = "นายมาทำอะไรที่นี่น่ะ... เบรนท์?",
  ui_story_5007_50071102_12_dialog_content = "ตอบฉันมาก่อน ขวดพวกนั้นมันอะไร?",
  ui_story_5007_50071102_13_dialog_content = "ยาช่วยลืมความเจ็บปวดไงล่ะ...",
  ui_story_5007_50071102_14_dialog_content = "นี่นายอยากจะทำลายตัวเองแบบนี้งั้นเหรอ?",
  ui_story_5007_50071102_15_dialog_content = "สงครามนั่นมันจบไปแล้ว และฉันก็ไม่ได้อยู่กับกองทัพอีกแล้ว...",
  ui_story_5007_50071102_16_dialog_content = "จากนี้ไป ฉันจะทำอะไรมันก็เรื่องของฉัน",
  ui_story_5007_50071102_17_dialog_content = "เรื่องของนายงั้นเหรอ?",
  ui_story_5007_50071102_18_dialog_content = "ดูสารรูปตัวเองสิ นายเคยเป็นทหารในตำนานนะ",
  ui_story_5007_50071102_19_dialog_content = "รู้มั้ยว่าคนอื่น ๆ เขาชื่นชมแล้วก็อยากจะมีพรสวรรค์ให้ได้ซักเสี้ยวนึงของนายก็ยังดี",
  ui_story_5007_50071102_20_dialog_content = "พรสวรรค์งั้นเหรอ? ของแบบนั้นมันจะประโยชน์อะไร",
  ui_story_5007_50071102_21_dialog_content = "แม้แต่สหายร่วมรบฉันก็ไม่มีปัญญาช่วยเอาไว้",
  ui_story_5007_50071102_22_dialog_content = "ฉันจำเด็กกำพร้าคนนั้นได้",
  ui_story_5007_50071102_23_dialog_content = "แต่ก็ยังรวบรวมความกล้าไปเล่าให้เด็กคนนั้นฟังไม่ได้ซักที...",
  ui_story_5007_50071102_24_dialog_content = "ว่าฉันเห็นอิคลิพไซท์แทงทะลุร่างของเบอร์นาร์ดต่อหน้าต่อตา",
  ui_story_5007_50071102_25_dialog_content = "ฉันช่วยเขาไว้ไม่ได้",
  ui_story_5007_50071102_26_dialog_content = "เขายอมสละชีวิตเพื่ออิลลูมินาต่างหากล่ะ!",
  ui_story_5007_50071102_27_dialog_content = "ทั้ง ๆ ที่เขาควรมีชีวิตต่อไปในฐานะฮีโร่",
  ui_story_5007_50071102_28_dialog_content = "เบอร์นาร์ดควรได้เป็นฮีโร่ที่เขาอยากจะเป็นมาตลอด นำพวกเราทุกคนไปสู่ชัยชนะ",
  ui_story_5007_50071102_29_dialog_content = "แทนที่จะต้องตายระหว่างที่หลบหนีแบบนั้น",
  ui_story_5007_50071102_30_dialog_content = "แต่เขาก็ช่วยชีวิตพวกเราและอีกหลายคนไว้ นี่ล่ะคือฮีโร่ที่แท้จริง",
  ui_story_5007_50071102_31_dialog_content = "ฮีโร่จะเป็นแรงบันดาลใจให้คนอื่น ๆ รอบตัวเสมอ แล้วฉันก็มั่นใจว่าเจตจำนงของเขาก็ส่งต่อมาถึงนายด้วย",
  ui_story_5007_50071102_32_dialog_content = "แต่แค่นายยังไม่รู้ตัวเท่านั้นเอง",
  ui_story_5007_50071102_33_dialog_content = "ฉันยังจำตอนที่เราตั้งหน่วยได้...",
  ui_story_5007_50071102_34_dialog_content = "นายกับเรวี่จะได้อยู่ทีมเมืองใต้ดินหมายเลข 24",
  ui_story_5007_50071102_35_dialog_content = "ยังไม่เคยคุยกันมาก่อนใช่มั้ย?",
  ui_story_5007_50071102_36_dialog_content = "เดี๋ยวฉันแนะนำให้ก็แล้วกัน",
  ui_story_5007_50071102_37_dialog_content = "เรวี่ นี่แกรม แกรม นี่เรวี่",
  ui_story_5007_50071102_38_dialog_content = "แนะนำตัวกับแกรมหน่อยสิ",
  ui_story_5007_50071102_39_dialog_content = "ฉันชื่อเร-วี่!",
  ui_story_5007_50071102_40_dialog_content = "นี่เข้าใจคำว่าแนะนำตัวรึเปล่าเนี่ย?",
  ui_story_5007_50071102_41_dialog_content = "ฉันรู้ว่าฉันเก่งกว่าคุณแน่นอน!",
  ui_story_5007_50071102_42_dialog_content = "เขาสู้ฉันไม่ได้หรอก! ถึงจะแก่ แต่ฉันก็ไม่มีทางออมมือแน่",
  ui_story_5007_50071102_43_dialog_content = "พูดอะไรของเธอน่ะ? ฉันจะให้พวกเธอสองคนรู้จักกัน ไม่ได้ให้สู้กันซักหน่อย",
  ui_story_5007_50071102_44_dialog_content = "น่าเบื่อชะมัด! ไม่เอาแล้ว ฉันไปฝึกต่อดีกว่า!",
  ui_story_5007_50071102_45_dialog_content = "เดี๋ยวก่อนสิ เธอไม่อยากฟังเรื่องของเบอร์นาร์ด พ่อของเธอเหรอ?",
  ui_story_5007_50071102_46_dialog_content = "พ่อของฉัน? คุณต้องการอะไรกันแน่?",
  ui_story_5007_50071102_47_dialog_content = "อย่าซีเรียสน่า",
  ui_story_5007_50071102_48_dialog_content = "พวกเราสองคนเป็นเพื่อนเก่าของพ่อเธอ เขาเป็นฮีโร่...",
  ui_story_5007_50071102_49_dialog_content = "ฉันรู้ว่าเขาเป็นฮีโร่ แล้วก็รู้ว่าเขาเก่งแค่ไหน แต่บางคนก็บอกว่าเพื่อนร่วมทีมของเขาเก่งกว่า!",
  ui_story_5007_50071102_50_dialog_content = "คุณเป็นเพื่อนร่วมทีมของพ่องั้นเหรอ?",
  ui_story_5007_50071102_51_dialog_content = "ไม่ ฉันไม่เก่งเท่าพ่อของเธอหรอก",
  ui_story_5007_50071102_52_dialog_content = "ฉันไม่สนหรอกว่าคุณจะเป็นอะไรกับพ่อ",
  ui_story_5007_50071102_53_dialog_content = "ฉันสนแต่ว่าจะต้องฝึกฝีมือให้แข็งแกร่ง เพื่อที่ฉันจะได้แซงหน้าฮีโร่อย่างเขา!",
  ui_story_5007_50071102_54_dialog_content = "เธอทำตัวงอแงน่ะ ฉันหยุดเธอแล้ว ตอนนี้เธอสงบใจพอที่จะบอกลานายแล้ว",
  ui_story_5007_50071102_55_dialog_content = "ฉันกล้าหาญ แล้วก็ต่อสู้อย่างนักรบที่แท้จริง ฉันเป็นคนแข็งแกร่ง แล้วก็ทำตามสัญญา",
  ui_story_5007_50071102_56_dialog_content = "ยังไงฉันก็จะสู้ต่อไปเพื่อเป้าหมาย...",
  ui_story_5007_50071102_57_dialog_content = "ในเมื่อตอนนี้ทุกคนเรียกคุณว่าฮีโร่ ฉันก็มีเป้าหมายอีกคนที่จะต้องแซงหน้า",
  ui_story_5007_50071102_58_dialog_content = "...",
  ui_story_5007_50071102_59_dialog_content = "ตามธรรมเนียมของสโตนฟอร์ซแล้ว ฉันคงต้องขอป้ายชื่อของนายไปล่ะนะ",
  ui_story_5007_50071102_60_dialog_content = "ฉันรู้ว่านายจะพูดอะไร",
  ui_story_5007_50071102_61_dialog_content = "ถ้านายยังอยู่ ก็คงจะพูดว่า...",
  ui_story_5007_50071102_62_dialog_content = "\"จงสู้ต่อไป\"",
  ui_story_5007_50071102_63_dialog_content = "\"จนกว่าชัยชนะจะมาถึง\"",
