  ui_story_5007_50071601_45_dialog_content = "โอ๊ะ ขอโทษค่ะ มือมันเผลอไปโดนน่ะ",
  ui_story_5007_50071601_46_dialog_content = "ให้ตายสิ... ช่างเหอะ อีกครึ่งชั่วโมงไปรวมพลที่ประตูสถานีนอกเมืองด้วย",
  ui_story_5007_50071601_47_dialog_content = "เดี๋ยวฉันยังต้องไปบอกคนอื่นอีก เธอล่วงหน้าไปก่อนเลย",
  ui_story_5007_50071601_48_dialog_content = "ฉันช่วยคุณได้นะ! เพราะฉันมี...",
