  ui_story_5007_50071601_49X1_dialog_content = "หยอกเล่นน่ะค่ะ แหะแหะ",
  ui_story_5007_50071601_49X2_dialog_content = "ช่วยจริงจังกว่านี้หน่อยได้มั้ย?",
  ui_story_5007_50071601_49X3_dialog_content = "ฉันรู้ว่าใคร ๆ ก็เห็นฉันเป็นคนพึ่งพาไม่ได้แล้วก็ขาดวุฒิภาวะ แต่ฉันเองก็เติบโตขึ้นเหมือนกันนะคะ!",
