  ui_story_5007_50071601_52_dialog_content = "เจ้าหน้าที่แกรม! ให้ตายเถอะ เจ้าหน้าที่แกรมพูดกับฉันจริง ๆ!",
  ui_story_5007_50071601_53_dialog_content = "สวัสดีครับ เจ้าหน้าที่แกรม ผมชื่อแพท ผม... ผมเป็นแฟนตัวยงของคุณเลยล่ะ!",
