  ui_story_5007_50071601_55_dialog_content = "เจ้าหน้าที่เบรนท์มักจะพูดถึงคุณระหว่างฝึกซ้อมรบเสมอ",
  ui_story_5007_50071601_56_dialog_content = "ผมเองก็มีความฝันว่าซักวันจะได้จัดการศัตรูคราวละเยอะ ๆ เหมือนคุณ!",
  ui_story_5007_50071601_57_dialog_content = "ถึงตอนนี้ผมจะเป็นแค่ทหารยาม แต่ผมก็พยายามอย่างเต็มที่!",
  ui_story_5007_50071601_58_dialog_content = "เข้าใจแล้ว ฉันเชื่อว่านายทำได้ ถ้าตั้งใจมากพอนะ ไอ้หนู",
  ui_story_5007_50071601_59_dialog_content = "ขอบคุณครับ!",
